 if(requested&&tabKeys.includes(requested))ui.tab=requested;
 else if(requested){renderDetail(x);return}
 if(ui.tab==='history'){renderTradeHistory();return}
 if(ui.tab==='suggestions'){renderAISuggestions();return}
