 const combinedCards=[...list.map(t=>({kind:'two',updated:t.updatedAt||'',row:t})),...multiList.map(t=>({kind:'multi',updated:t.updatedAt||t.createdAt||'',row:t}))].sort((x,y)=>String(y.updated).localeCompare(String(x.updated)));
