function rejection(t,a){const reason=Object.values(t.votes||{}).filter(x=>x.vote==='reject').map(x=>x.comment).join(' ');if(a.role==='commissioner')return`<article class="decision-composer card"><div class="decision-composer__header"><span class="committee-lock"><svg><use href="#icon-gavel"></use></svg></span><div><span class="eyebrow">Commissioner-only</span><h2>Prepare separate rejection DMs</h2><p>Nothing is public. Edit the explanation and send it privately to each owner.</p></div></div><label class="field"><span>Reason and suggested correction</span><textarea data-rejection-reason>${escapeHtml(reason||'Improve the premium asset or draft-pick return before resubmitting.')}</textarea></label><div class="dm-recipient-grid"><span>DM to ${owner(t.teamAId).handle}</span><span>DM to ${owner(t.teamBId).handle}</span></div><button class="button button--danger" data-send-dms="${t.id}">Send private commissioner DMs</button></article>`;return`<article class="committee-wait card"><span class="committee-lock"><svg><use href="#icon-clock"></use></svg></span><div><span class="eyebrow">Private result in progress</span><h2>The committee declined the trade</h2><p>The commissioner is preparing individual DMs explaining why and how to revise it.</p></div></article>`}
function rejected(t,a){return`<article class="decision-card decision-card--rejected card"><span><svg><use href="#icon-close"></use></svg></span><div><span class="eyebrow">Private commissioner DM</span><h2>Trade not approved</h2><p>${escapeHtml(t.decision?.reason||'The committee declined this trade.')}</p><div class="decision-meta"><span>Visibility <strong>Each owner only</strong></span><span>Public post <strong>None</strong></span></div>${involved(t,a)?'<button class="button button--secondary" data-revise>Revise and resubmit</button>':''}</div></article>`}
function versionHistory(t){return`<article class="version-history card"><div class="card-header"><div><span class="eyebrow">Immutable offer history</span><h3>${t.versions.length} saved version${t.versions.length===1?'':'s'}</h3></div><span class="pill pill--neutral">Previous packages preserved</span></div><div class="version-history-list">${[...t.versions].reverse().map(q=>`<details ${q.number===t.currentVersion?'open':''}><summary><span><b>Version ${q.number}</b><small>${escapeHtml(acc(q.proposerId)?.handle||'Owner')} · ${escapeHtml(q.createdAt)}</small></span><strong>${total(q.assetsA,q.assetsB).toLocaleString()} ↔ ${total(q.assetsB,q.assetsA).toLocaleString()}</strong></summary><div class="version-package-grid"><div>${q.assetsA.map(a=>renderAsset(a)).join('')}</div><div>${q.assetsB.map(a=>renderAsset(a)).join('')}</div></div></details>`).join('')}</div></article>`}
function activityTimeline(t){const items=[...(t.activity||[])].reverse();return`<article class="activity-timeline card"><div class="card-header"><div><span class="eyebrow">Negotiation activity</span><h3>Private timeline</h3></div></div><div class="activity-list">${items.length?items.map(x=>`<div class="activity-item"><span class="activity-dot"></span><div><strong>${escapeHtml(x.text)}</strong><small>${escapeHtml(acc(x.authorId)?.handle||'System')} · ${escapeHtml(x.at)}</small></div></div>`).join(''):'<div class="empty-mini">No activity yet.</div>'}</div><details class="timeline-version-history"><summary>View ${t.versions.length} trade version${t.versions.length===1?'':'s'}</summary><div class="version-history-list">${[...t.versions].reverse().map(q=>`<details ${q.number===t.currentVersion?'open':''}><summary><span><b>Version ${q.number}</b><small>${escapeHtml(acc(q.proposerId)?.handle||'Owner')} · ${escapeHtml(q.createdAt)}</small></span><strong>${total(q.assetsA,q.assetsB).toLocaleString()} ↔ ${total(q.assetsB,q.assetsA).toLocaleString()}</strong></summary><div class="version-package-grid"><div>${q.assetsA.map(a=>renderAsset(a)).join('')}</div><div>${q.assetsB.map(a=>renderAsset(a)).join('')}</div></div></details>`).join('')}</div></details></article>`}
function renderDetail(x){const t=trade(x);if(!t||!visible(t)){ui.activeNegotiationId=null;pageContent.innerHTML=`<div class="page-heading"><div><span class="eyebrow">Private transaction</span><h1>Trade unavailable</h1><p>You are not authorized to view this stage.</p></div></div><article class="empty-state card"><button class="button button--primary" data-open-login>Switch mock account</button></article>`;return}ui.activeNegotiationId=t.negotiationId||t.id;if(t.status==='draft'){initBuilder(t);renderBuilder();return}markViewed(t);(store.notifications||[]).forEach(n=>{if(n.accountId===me().id&&String(n.tradeId)===String(t.id))n.read=true});const a=me(),v=ver(t),participant=involved(t,a),A=teamById(t.teamAId),B=teamById(t.teamBId),proposer=acc(v.proposerId);let flow=t.status==='negotiating'&&participant?chat(t,v,a):t.status==='committee'?committeeView(t,v,a):t.status==='approved'?approved(t):t.status==='committee-rejected'?rejection(t,a):t.status==='rejected'?rejected(t,a):`<article class="decision-card decision-card--rejected card"><div><h2>${t.status==='withdrawn'?'Offer withdrawn':t.status==='expired'?'Offer expired':'Offer declined'}</h2><p>Nothing was sent to committee or published.</p></div></article>`;pageContent.innerHTML=`<div class="page-heading trade-detail-heading"><div><button class="text-button" data-route="trade-center"><svg style="transform:rotate(180deg)"><use href="#icon-arrow"></use></svg>Trade Center</button><span class="eyebrow">Private Trade #${t.id}</span><h1>${A.abbr} ↔ ${B.abbr} Trade</h1><p>${escapeHtml(v.note||'Review the complete trade package, valuation, messages, and timeline.')}</p></div><div class="heading-actions">${twoTeamHeaderActions(t,v,a)}</div></div>${t.status==='committee'?`<article class="trade-awaiting-committee-banner"><strong>ACCEPTED BY BOTH PARTIES</strong><span>AWAITING TRADE COMMITTEE REVIEW</span></article>`:['rejected','committee-rejected','cancelled','withdrawn'].includes(t.status)?`<article class="trade-final-status-banner is-${t.status}"><strong>${t.status==='withdrawn'?'WITHDRAWN':t.status==='cancelled'?'REJECTED / CANCELLED':t.status==='committee-rejected'?'REJECTED BY TRADE COMMITTEE':`REJECTED BY ${escapeHtml(t.rejectedByName||'PARTICIPANT').toUpperCase()}`}</strong><span>${escapeHtml(t.cancelReason||'This trade is closed and cannot continue.')}</span></article>`:''}${sideDetail(t,v,calcVisible(t,a))}${calcVisible(t,a)?calculationPanel(t,v,'Fair Trade Calculator'):`<article class="calculation-hidden card"><span><svg><use href="#icon-eye"></use></svg></span><div><strong>Private calculation</strong><p>Only the involved owners and eligible Trade Committee reviewers can view this negotiation.</p></div></article>`}${flow}${participant?activityTimeline(t):''}`}
function accept(x){const t=trade(x),v=ver(t),a=me();if(t&&blockForApprovedAsset('two',t))return;if(!t||!sameParty(a,v.targetId))return;t.status='committee';t.updatedAt=now();t.votes={};const reviewers=[...committee,commissioner],eligible=eligibleCommittee(t);t.review={openedAt:t.updatedAt,submittedVersion:v.number,threshold:3,totalMembers:eligible.length,recusedMemberIds:reviewers.filter(m=>committeeConflict(t,m)).map(m=>m.id)};reviewers.forEach(m=>notify(m.id,t.negotiationId||t.id,committeeConflict(t,m)?'Review recusal applied':'Trade review assigned',committeeConflict(t,m)?`Trade #${t.negotiationId||t.id} involves your franchise. Your review controls are locked.`:`Trade #${t.negotiationId||t.id} is ready for your confidential review.`,'committee'));t.chat.push({id:id(),authorId:'system',text:`${a.handle} accepted Version ${v.number}. Sent to review.`,at:now()});activity(t,'accepted',`${a.handle} accepted Version ${v.number}.`,a.id);notify(v.proposerId,t.id,'Offer accepted',`${a.handle} accepted Trade #${t.id}.`,'accepted');audit(`Trade #${t.id} entered confidential review.`);save();showToast('Trade sent to review','Eligible Trade Committee members and Commissioners can now review the locked version.');renderDetail(t.id)}
function decline(x){const t=trade(x),v=ver(t),a=me();if(!t||!sameParty(a,v.targetId))return;t.status='rejected';t.rejectedBy=a.id;t.rejectedByName=a.handle;t.rejectionSource='owner';t.updatedAt=now();activity(t,'rejected',`${a.handle} rejected Version ${v.number}.`,a.id);notify(v.proposerId,t.id,'Offer rejected',`${a.handle} rejected Trade #${t.id}.`,'rejected');audit(`Trade #${t.id} rejected by ${a.handle}.`);save();showToast('Trade rejected','The rejection was saved in the Rejected tab.');renderDetail(t.id)}
function canWithdraw(t,a=me()){if(!t||t.status!=='negotiating')return false;const v=ver(t),proposer=acc(v?.proposerId);if(!v||!proposer)return false;return sameParty(a,v.proposerId)||(a.teamId&&proposer.teamId&&a.teamId===proposer.teamId)}
function withdraw(value){migrateNegotiations();const requestedId=canonicalNegotiationId(value),t=trade(requestedId),a=me();if(!t){console.error('[Negotiation Engine] withdraw lookup failed',{value,requestedId,activeNegotiationId:ui.activeNegotiationId,routeNegotiationId:routeNegotiationId(),available:negotiations().map(n=>({id:n.id,negotiationId:n.negotiationId,status:n.status}))});showToast('Unable to withdraw','The active negotiation could not be resolved. Open the trade from Trade Center and try again.');return}const negotiationId=t.negotiationId||t.id;if(t.status!=='negotiating'){showToast('Offer already closed','This negotiation is no longer active.');renderDetail(t.negotiationId);return}const v=ver(t);if(!canWithdraw(t,a)){showToast('Only the current proposer can withdraw',`Version ${v?.number||t.currentVersion} belongs to ${escapeHtml(acc(v?.proposerId)?.handle||'the other owner')}.`);return}const actorId=actingOwnerId(a);t.status='withdrawn';t.updatedAt=now();t.closedBy=actorId;t.closedAt=t.updatedAt;t.closeReason='withdrawn-by-current-proposer';activity(t,'withdrawn',`${acc(actorId)?.handle||a.handle} withdrew Version ${v.number}.`,actorId);notify(v.targetId,t.negotiationId,'Offer withdrawn',`${acc(actorId)?.handle||a.handle} withdrew Trade #${t.negotiationId}.`,'withdrawn');audit(`Trade #${t.negotiationId} was withdrawn by ${acc(actorId)?.handle||a.handle}.`);save();showToast('Offer withdrawn','The negotiation is closed and its complete history remains available.');renderDetail(t.negotiationId)}
function sendChat(x){const t=trade(x),input=document.querySelector('[data-chat-input]'),text=input?.value.trim();if(!t||!text||!involved(t))return;const a=me(),otherId=participants(t).find(v=>v!==a.id);t.chat.push({id:id(),authorId:a.id,text:text.slice(0,500),at:now()});activity(t,'message',`${a.handle} added a negotiation message.`,a.id);notify(otherId,t.id,'New trade message',`${a.handle}: ${text.slice(0,90)}`,'message');t.updatedAt=now();save();renderDetail(t.id);setTimeout(()=>document.querySelector('[data-chat-input]')?.focus(),0)}
function resolve(t){const c=voteCounts(t);if(c.approve>=3){const limitRows=approvalLimitRowsForLegacy(t);const blocked=limitRows.filter(r=>!r.allowed);if(blocked.length){t.votes={};t.updatedAt=now();activity(t,'approval-blocked',approvalLimitMessage(blocked),'system');showToast('Trade approval blocked',approvalLimitMessage(blocked));return false}t.status='approved';t.updatedAt=now();t.publicAt=now();t.decision={result:'approved',approve:c.approve,reject:c.reject,abstain:c.abstain,at:t.updatedAt};activity(t,'committee-approved',`Trade approved by committee ${c.approve}-${c.reject}${c.abstain?` with ${c.abstain} abstention${c.abstain===1?'':'s'}`:''}.`,'system');participants(t).forEach(pid=>notify(pid,t.negotiationId||t.id,'Trade approved',`Trade #${t.negotiationId||t.id} was approved by the committee.`,'approved'));audit(`Trade #${t.negotiationId||t.id} approved ${c.approve}-${c.reject} and posted publicly.`);showToast('Trade approved','The final terms are now public in League News.');cancelConflictingCommitteeTrades();return true}if(c.reject>=3){t.status='committee-rejected';t.updatedAt=now();t.rejectionSource='committee';t.rejectedByName='Trade Committee';t.decision={result:'committee-rejected',approve:c.approve,reject:c.reject,abstain:c.abstain,at:t.updatedAt};activity(t,'committee-rejected',`Trade rejected by committee ${c.reject}-${c.approve}.`,'system');notify('commissioner',t.negotiationId||t.id,'Committee decision ready',`Trade #${t.negotiationId||t.id} requires private rejection messaging.`,'committee-rejected');audit(`Trade #${t.negotiationId||t.id} rejected; commissioner DMs pending.`);showToast('Trade rejected','The commissioner must now send the private decision explanation.');return true}showToast('Ballot recorded',`${c.approve} approve · ${c.reject} reject · ${c.abstain} abstain`);return false}
function vote(x,result){const t=trade(x),a=me(),input=document.querySelector('[data-vote-comment]'),comment=input?.value.trim()||'';if(!t||!canVoteOnTrades(a)||!eligibleCommittee(t).some(r=>r.id===a.id)||t.status!=='committee'){showToast('Review unavailable','This review is no longer open.');return}if(committeeConflict(t,a)){showToast('Voting disabled','You cannot review a trade involving your own franchise.');return}if(!['approve','reject','abstain'].includes(result))return;if(result==='reject'&&!comment){showToast('Rationale required','Explain the competitive-balance concern and what would make the trade acceptable.');input?.focus();return}if(result==='abstain'&&!comment){showToast('Abstention note required','Briefly explain why you cannot cast a decision.');input?.focus();return}const prior=t.votes?.[a.id];t.votes=t.votes||{};t.votes[a.id]={vote:result,comment:comment||(result==='approve'?'No competitive-balance concern.':'Reviewer abstained.'),at:now(),version:vNumber(t),role:a.role};t.updatedAt=now();activity(t,'committee-vote',`${a.handle} ${prior?'updated':'submitted'} a confidential ${a.role==='commissioner'?'commissioner review':'committee ballot'}.`,a.id);resolve(t);save();renderDetail(t.negotiationId||t.id)}
function vNumber(t){return Number(t.currentVersion||ver(t)?.number||1)}
function sendDms(x){const t=trade(x),reason=document.querySelector('[data-rejection-reason]')?.value.trim();if(!t||me().role!=='commissioner'||!reason){showToast('Explanation required','Write the reason before sending.');return}t.status='rejected';t.updatedAt=now();t.decision={result:'rejected',reason,at:now(),sentBy:me().id};audit(`Commissioner sent private rejection DMs for Trade #${t.id}.`);save();showToast('Private DMs sent','No public post was created.');renderDetail(t.id)}
function onBlock(p){const v=store.block?.[p.id];return typeof v==='object'?v.active!==false:typeof v==='boolean'?v:p.tradeBlock}
function blockWant(key){return escapeHtml(store.blockNotes?.[key]||'Open to fair offers')}
function pickBlockKey(teamId,year,round){return`${teamId}:${year}:${round}`}
function onBlockPick(key){return!!store.blockPicks?.[key]}
function askBlockQuestion(key,label,teamId){const text=prompt(`Ask ${teamById(teamId)?.owner||'the owner'} about ${label}:`);if(!text?.trim())return;const recipient=owner(teamId);notify(recipient?.id,key,'Trade block question',`${me().handle}: ${text.trim().slice(0,180)}`,'block-question');save();showToast('Question sent',`The ${teamById(teamId)?.fullName||'team'} owner was notified privately.`)}
function startBlockAsset(token){const a=parse(token),current=me();if(!a||!current.teamId)return;const targetTeam=a.type==='player'?playerById(a.id)?.teamId:a.teamId;if(!targetTeam||targetTeam===current.teamId)return;initBuilder();ui.builder.teamBId=targetTeam;ui.builder.assetsB=[a];setRoute('trade-center/new')}
function renderReplay(t){
 if(!t)return showToast('Replay unavailable','The negotiation record could not be loaded.');
 let modal=document.querySelector('[data-replay-modal]');
 if(!modal){modal=document.createElement('div');modal.className='replay-modal';modal.setAttribute('data-replay-modal','');document.body.appendChild(modal)}
 const A=teamById(t.teamAId),B=teamById(t.teamBId);if(!A||!B)return showToast('Replay unavailable','The teams in this negotiation could not be loaded.');
 modal.className='replay-modal is-open';
 modal.setAttribute('aria-hidden','false');
 modal.innerHTML=`<div class="replay-backdrop" data-close-replay></div><section class="replay-dialog" role="dialog" aria-modal="true"><header><div><span class="eyebrow">Trade Replay · #${t.id}</span><h2>${A.abbr} ↔ ${B.abbr}</h2><p>Every proposal is preserved under one permanent negotiation.</p></div><button class="icon-button" data-close-replay aria-label="Close replay">×</button></header><div class="replay-steps">${t.versions.map((v,i)=>{const prev=t.versions[i-1],newA=prev?new Set(v.assetsA.filter(a=>!prev.assetsA.some(x=>assetKey(x)===assetKey(a))).map(assetKey)):new Set(),newB=prev?new Set(v.assetsB.filter(a=>!prev.assetsB.some(x=>assetKey(x)===assetKey(a))).map(assetKey)):new Set(),removedA=prev?prev.assetsA.filter(a=>!v.assetsA.some(x=>assetKey(x)===assetKey(a))):[],removedB=prev?prev.assetsB.filter(a=>!v.assetsB.some(x=>assetKey(x)===assetKey(a))):[];return`<article class="replay-step ${i===t.versions.length-1?'is-final':''}"><div class="replay-step__head"><span>Version ${v.number}</span><strong>${escapeHtml(acc(v.proposerId)?.handle||'Owner')}</strong><small>${escapeHtml(v.createdAt||'')}</small></div><div class="replay-packages"><div><h4>${A.abbr} sends</h4>${v.assetsA.map(a=>renderAsset(a,{isNew:newA.has(assetKey(a))})).join('')}${removedNote(removedA)}</div><div><h4>${B.abbr} sends</h4>${v.assetsB.map(a=>renderAsset(a,{isNew:newB.has(assetKey(a))})).join('')}${removedNote(removedB)}</div></div>${v.note?`<p class="replay-note">“${escapeHtml(v.note)}”</p>`:''}</article>`}).join('')}</div><footer><span>${t.versions.length} versions · Final result: ${escapeHtml(historyDecisionLabel(t))}</span><button class="button button--primary" data-close-replay>Close replay</button></footer></section>`;
 document.body.style.overflow='hidden';
 modal.querySelector('[data-close-replay]')?.focus();
}
function closeReplay(){const modal=document.querySelector('[data-replay-modal]');if(modal){modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true')}document.body.style.overflow=''}

