// v5.7.0a — Unified Private Trade Builder
function initBuilder(t=null){
 const a=me();
 if(t){const v=ver(t);ui.builder={tradeId:t.id,teamIds:[t.teamAId,t.teamBId],assetsByTeam:{[t.teamAId]:structuredClone(v.assetsA),[t.teamBId]:structuredClone(v.assetsB)},destinations:{},note:''};return}
 const own=a.teamId||'dal';ui.builder={tradeId:null,teamIds:[own],assetsByTeam:{[own]:[]},destinations:{},note:''}
}
function builderSnapshot(b=ui.builder){
 if(!b)return null;
 const u=ensureUnifiedBuilder();
 return {teamIds:[...u.teamIds],assetsByTeam:structuredClone(u.assetsByTeam||{}),destinations:{...(u.destinations||{})},note:u.note||'',tradeId:u.tradeId||null,multiTradeId:u.multiTradeId||null,savedAt:Date.now()};
}
function builderHasWork(b=ui.builder){
 if(!b)return false;const u=ensureUnifiedBuilder();
 return u.teamIds.length>1||Object.values(u.assetsByTeam||{}).some(v=>Array.isArray(v)&&v.length)||Object.keys(u.destinations||{}).length||Boolean((u.note||'').trim());
}
function persistBuilderRecovery(){
 if(!builderHasWork())return;try{localStorage.setItem(BUILDER_RECOVERY,JSON.stringify(builderSnapshot()))}catch{}
}
function clearBuilderRecovery(){try{localStorage.removeItem(BUILDER_RECOVERY)}catch{}}
function readBuilderRecovery(){try{return JSON.parse(localStorage.getItem(BUILDER_RECOVERY)||'null')}catch{return null}}
function restoreBuilderRecovery(){const r=readBuilderRecovery();if(!r)return false;ui.builder={teamAId:r.teamIds?.[0]||me()?.teamId,teamBId:r.teamIds?.[1]||null,teamIds:r.teamIds||[],assetsByTeam:r.assetsByTeam||{},destinations:r.destinations||{},assetsA:[],assetsB:[],note:r.note||'',tradeId:r.tradeId||null,multiTradeId:r.multiTradeId||null};ensureUnifiedBuilder();return true}
function resetUnifiedBuilder(){const a=me();ui.builder={tradeId:null,teamAId:a.teamId,teamBId:null,teamIds:[a.teamId],assetsByTeam:{[a.teamId]:[]},destinations:{},assetsA:[],assetsB:[],note:''};clearBuilderRecovery();}
function leaveBuilder(mode){
 if(mode==='continue'){document.querySelector('[data-builder-leave-modal]')?.classList.remove('is-open');builderNavigationGuard=false;try{history.replaceState({fgcTradeBuilder:true},'','#trade-center/new')}catch{}return}
 if(mode==='save'){saveCurrentBuilderDraft();return}
 if(mode==='discard'){clearBuilderRecovery();ui.builder=null;setRoute('trade-center');return}
}
function unifiedBuilderTeamIds(b=ui.builder){return Array.isArray(b?.teamIds)?b.teamIds.filter(Boolean):[b?.teamAId,b?.teamBId].filter(Boolean)}
function ensureUnifiedBuilder(){
 const a=me();
 if(!ui.builder)initBuilder();
 const b=ui.builder;
 if(!Array.isArray(b.teamIds))b.teamIds=[b.teamAId,b.teamBId].filter(Boolean);
 b.teamIds=[...new Set(b.teamIds)].slice(0,4);
 b.assetsByTeam=b.assetsByTeam||{};
 b.destinations=b.destinations||{};
 b.teamIds.forEach((teamId,index)=>{
  if(!Array.isArray(b.assetsByTeam[teamId])){
   if(index===0&&Array.isArray(b.assetsA))b.assetsByTeam[teamId]=b.assetsA;
   else if(index===1&&Array.isArray(b.assetsB))b.assetsByTeam[teamId]=b.assetsB;
   else b.assetsByTeam[teamId]=[];
  }
  ui.builderSearch[teamId]=ui.builderSearch[teamId]||'';
  ui.builderType[teamId]=ui.builderType[teamId]||'all';
  ui.builderPosition[teamId]=ui.builderPosition[teamId]||'All';
 });
 b.teamAId=b.teamIds[0]||a.teamId;
 b.teamBId=b.teamIds[1]||null;
 b.assetsA=b.assetsByTeam[b.teamAId]||[];
 b.assetsB=b.teamBId?(b.assetsByTeam[b.teamBId]||[]):[];
 return b;
}
function unifiedAssetToken(teamId,asset){return `${teamId}|${assetKey(asset)}`}
function unifiedDestination(teamId,asset){
 const b=ensureUnifiedBuilder(),key=unifiedAssetToken(teamId,asset),valid=b.teamIds.filter(id=>id!==teamId);
 if(!valid.includes(b.destinations[key]))b.destinations[key]=valid[0]||'';
 return b.destinations[key];
}
function unifiedTransfers(){
 const b=ensureUnifiedBuilder();
 return b.teamIds.flatMap(fromTeamId=>(b.assetsByTeam[fromTeamId]||[]).map(asset=>({fromTeamId,toTeamId:unifiedDestination(fromTeamId,asset),asset})));
}
function unifiedFlow(){
 const b=ensureUnifiedBuilder(),transfers=unifiedTransfers();
 return b.teamIds.map(teamId=>({teamId,sends:transfers.filter(t=>t.fromTeamId===teamId&&t.toTeamId).length,receives:transfers.filter(t=>t.toTeamId===teamId).length}));
}
function unifiedReady(){const b=ensureUnifiedBuilder(),flow=unifiedFlow();return b.teamIds.length>=2&&flow.every(row=>row.sends>0&&row.receives>0)}
function unifiedParticipantSide(teamId){
 const b=ensureUnifiedBuilder(),t=teamById(teamId),assets=b.assetsByTeam[teamId]||[],positions=['All',...new Set(players.filter(p=>p.teamId===teamId).map(p=>p.position))],playerAssets=assets.filter(a=>a.type==='player').map(a=>playerById(a.id)).filter(Boolean),capOut=playerAssets.reduce((n,p)=>n+Number(p.capHit||0),0);
 return `<article class="trade-builder-side card unified-participant-card"><div class="trade-builder-side__header">${renderTeamMark(t,'team-logo')}<div><span class="eyebrow">Select ${t.abbr} assets</span><h3>${escapeHtml(t.fullName)}</h3></div>${teamId!==b.teamIds[0]?`<button class="icon-button" data-remove-builder-team="${teamId}" aria-label="Remove ${escapeHtml(t.fullName)}">×</button>`:''}</div><div class="builder-side-summary"><span>${assets.length} selected</span><span>${playerAssets.length} players</span><span>${formatMoney(capOut)} cap represented</span>${assets.length?`<button class="text-button" data-clear-side="${teamId}">Clear team</button>`:''}</div><div class="asset-browser"><div class="asset-browser-controls"><div class="segmented-tabs segmented-tabs--small">${[['all','All'],['players','Players'],['picks','Picks']].map(([v,l])=>`<button data-builder-type="${v}" data-side="${teamId}" class="${ui.builderType[teamId]===v?'is-active':''}">${l}</button>`).join('')}</div><label class="field field--grow"><span>Search assets</span><input data-builder-search="${teamId}" value="${escapeHtml(ui.builderSearch[teamId]||'')}" placeholder="Player, position, year or round..."></label><label class="field builder-position-filter"><span>Position</span><select data-builder-position="${teamId}" ${ui.builderType[teamId]==='picks'?'disabled':''}>${positions.map(pos=>`<option ${ui.builderPosition[teamId]===pos?'selected':''}>${pos}</option>`).join('')}</select></label></div><div class="asset-results">${assetResults(teamId,teamId,assets)}</div></div></article><div class="builder-leave-modal" data-builder-leave-modal><button class="builder-leave-backdrop" data-builder-leave="continue" aria-label="Continue editing"></button><section class="builder-leave-dialog" role="dialog" aria-modal="true"><span class="eyebrow">Unsaved Trade Draft</span><h2>Trade assets are not saved</h2><p>Would you like to continue editing, save this unfinished trade as a draft, or discard the changes?</p><div class="heading-actions"><button class="button button--ghost" data-builder-leave="continue">Continue Editing</button><button class="button button--secondary" data-builder-leave="save">Save as Draft</button><button class="button button--danger" data-builder-leave="discard">Discard Changes</button></div></section></div>`
 persistBuilderRecovery();
}
function unifiedDraftRow(fromTeamId,asset){
 const b=ensureUnifiedBuilder(),from=teamById(fromTeamId),to=unifiedDestination(fromTeamId,asset),p=asset.type==='player'?playerById(asset.id):null;
 const title=asset.type==='player'?p?.name:`${asset.year} Round ${asset.round} Pick`;
 const meta=asset.type==='player'?`${p?.position||'—'} · ${p?.dev||'Normal'} · ${p?.overall||'—'} OVR`:`${from?.abbr||''} pick · ${draftDistance(asset.year)} draft${draftDistance(asset.year)===1?'':'s'} away`;
 return `<div class="unified-draft-asset"><button type="button" class="unified-draft-asset__identity" ${asset.type==='player'?`data-open-value-card="${asset.id}"`:`data-open-pick-card="${asset.teamId}:${asset.year}:${asset.round}"`}><span class="pick-mark">${asset.type==='player'?(p?.position||'P'):`R${asset.round}`}</span><span><strong>${escapeHtml(title||'Asset')}</strong><small>${escapeHtml(meta)}</small></span><b>${value(asset).toLocaleString()}</b></button><div class="unified-draft-asset__flow"><span>${escapeHtml(from?.abbr||fromTeamId)} sends to</span><select data-unified-destination="${escapeHtml(unifiedAssetToken(fromTeamId,asset))}">${b.teamIds.filter(id=>id!==fromTeamId).map(id=>`<option value="${id}" ${id===to?'selected':''}>${escapeHtml(teamById(id)?.abbr||id)} · ${escapeHtml(teamById(id)?.fullName||id)}</option>`).join('')}</select><button class="icon-button" data-remove-unified-asset="${escapeHtml(unifiedAssetToken(fromTeamId,asset))}" aria-label="Remove asset">×</button></div></div>`
}
function unifiedDraftPanel(){
 const b=ensureUnifiedBuilder(),rows=b.teamIds.flatMap(teamId=>(b.assetsByTeam[teamId]||[]).map(asset=>unifiedDraftRow(teamId,asset))),flow=unifiedFlow(),ready=unifiedReady();
 return `<section class="unified-trade-draft card"><div class="card-header"><div><span class="eyebrow">Private trade draft</span><h2>Direct every asset</h2><p>Select the receiving franchise for every player and pick in the transaction.</p></div><span class="pill ${ready?'pill--success':'pill--danger'}">${ready?'Ready to submit':'Action required'}</span></div>${ready?'':`<div class="unified-flow-warning" role="alert"><strong>ALL TEAMS MUST SEND AND RECEIVE ITEMS.</strong><span>Add assets and assign destinations until every participating franchise has at least one outgoing and one incoming item.</span></div>`}<div class="unified-flow-status">${flow.map(row=>{const team=teamById(row.teamId),ok=row.sends&&row.receives;return`<div class="${ok?'is-ready':'is-missing'}">${renderTeamMark(team,'team-logo')}<span><strong>${escapeHtml(team.abbr)}</strong><small>Sends ${row.sends} · Receives ${row.receives}</small></span></div>`}).join('')}</div><div class="unified-draft-assets">${rows.length?rows.join(''):'<div class="asset-empty"><span>+</span><p>Select players or picks from the team asset tables above.</p></div>'}</div></section>`
}
function unifiedLiveFairnessPanel(){const b=ensureUnifiedBuilder(),transfers=unifiedTransfers(),t={teamIds:[...b.teamIds],transfers};if(!transfers.length)return`<article class="private-calculation valuation-panel card live-fairness-panel"><div class="private-calculation__header"><div><span class="eyebrow">Live calculator</span><h3>Fair Trade Calculator</h3><p>Add assets to see each team's incoming and outgoing value update in real time.</p></div><span class="pill pill--neutral">Waiting for assets</span></div></article>`;return multiFairnessPanel(t).replace('multi-fairness-panel','multi-fairness-panel live-fairness-panel').replace('Multi-team valuation','Live draft valuation')}
function unifiedTradeLimitPanel(){const rules=tradeRules(),rows=builderTradeLimitRows(),valid=rows.every(r=>r.allowed);return`<article class="card trade-limit-preview"><div class="card-header"><div><span class="eyebrow">Commissioner trade rules</span><h3>Season Trade Usage</h3><p>${rules.limitEnabled?`Each team may use ${rules.seasonTradeLimit} trades this season. Up to ${rules.playersPerTradeUnit} players and ${rules.picksPerTradeUnit} picks sent by one team count as one trade.`:'Season trade limits are currently disabled. Asset thresholds are still shown for transparency.'}</p></div><span class="pill ${!rules.limitEnabled?'pill--neutral':valid?'pill--success':'pill--danger'}">${!rules.limitEnabled?'Unlimited':valid?'Within limits':'Limit exceeded'}</span></div><div class="trade-limit-team-grid">${rows.map(row=>`<div class="${row.allowed?'is-ready':'is-over'}">${renderTeamMark(row.team,'team-logo')}<span><strong>${escapeHtml(row.team.abbr)} · ${row.units} trade${row.units===1?'':'s'}</strong><small>${row.players} player${row.players===1?'':'s'} · ${row.picks} pick${row.picks===1?'':'s'} · ${rules.limitEnabled?`${row.used} used / ${row.remaining} remaining`:'Unlimited season'}</small></span></div>`).join('')}</div>${valid?'':`<div class="unified-flow-warning" role="alert"><strong>TRADE LIMIT EXCEEDED.</strong><span>${escapeHtml(tradeLimitMessage())}</span></div>`}</article>`}
function builderActionButtons(isEditing=false){
 const label=isEditing?'Save Trade Changes':'Send Trade Offer';
 return `<div class="builder-action-buttons"><button type="button" class="button button--danger button--subtle" data-clear-trade>Clear Trade</button><button type="button" class="button button--secondary" data-save-draft>Save Trade Offer</button><button type="button" class="button button--primary" data-submit-trade>${label}</button></div>`;
}
function renderBuilder(){const a=me();if(!ui.builder&&readBuilderRecovery())restoreBuilderRecovery();if(!canCreateTrade(a)){pageContent.innerHTML=`<div class="page-heading"><div><span class="eyebrow">Owner permission required</span><h1>Private Trade Builder</h1><p>Committee accounts cannot create owner offers.</p></div></div><article class="empty-state card"><h2>Switch to a team owner</h2><button class="button button--primary" data-open-login>Switch account</button></article>`;return}
 const b=ensureUnifiedBuilder(),edit=b.tradeId?trade(b.tradeId):null,available=teams.filter(t=>!b.teamIds.includes(t.id)),limitsValid=builderTradeLimitsValid();
 pageContent.innerHTML=`<div class="page-heading"><div><button class="text-button" data-builder-back><svg style="transform:rotate(180deg)"><use href="#icon-arrow"></use></svg>${edit?`Trade #${edit.id}`:'Trade Center'}</button><span class="eyebrow">Unified private trade workspace</span><h1>${edit?'Modify Trade':'Create a New Trade'}</h1><p>Add up to four franchises, select assets with the familiar player and pick filters, then direct each item inside one private trade draft.</p></div><div class="builder-heading-actions"><span class="pill pill--accent">${b.teamIds.length} of 4 teams</span>${builderActionButtons(Boolean(edit))}</div></div><div class="private-workspace-label"><span class="status-dot status-dot--live"></span><strong>Private calculator session</strong><span>Visible only to participating owners until committee review</span></div><div class="trade-builder-toolbar card unified-team-toolbar"><label class="field"><span>Your team</span><select disabled><option>${escapeHtml(teamById(b.teamIds[0]).fullName)}</option></select></label><label class="field field--grow"><span>Trade partner</span><select data-builder-team-select ${b.teamIds.length>=4?'disabled':''}><option value="">Select another team...</option>${available.map(t=>{const rem=remainingTradeCredits(t.id),disabled=tradeRules().limitEnabled&&rem<=0;return`<option value="${t.id}" ${disabled?'disabled':''}>${escapeHtml(t.abbr)} - ${escapeHtml(t.fullName)} - ${escapeHtml(t.owner)} - ${tradeRules().limitEnabled?`${rem} Trade${rem===1?'':'s'} Remaining`:'Unlimited Trades'}</option>`}).join('')}</select></label><button class="button button--secondary" data-add-builder-team ${b.teamIds.length>=4?'disabled':''}>Add</button></div><div class="unified-participant-grid">${b.teamIds.map(unifiedParticipantSide).join('')}</div>${unifiedDraftPanel()}${unifiedLiveFairnessPanel()}${unifiedTradeLimitPanel()}<article class="card trade-note-card"><label class="field"><span>Message to all participating owners</span><textarea data-builder-note placeholder="Explain the complete transaction...">${escapeHtml(b.note||'')}</textarea></label><div class="trade-note-card__footer"><span>Every owner accepts the same complete package. An approved trade remains pending Madden execution and does not modify site rosters.</span><div class="heading-actions">${builderActionButtons(Boolean(edit))}</div></div></article>`
}

function syncLegacyTwoTeamBuilder(){const b=ensureUnifiedBuilder();b.teamAId=b.teamIds[0];b.teamBId=b.teamIds[1];b.assetsA=b.assetsByTeam[b.teamAId]||[];b.assetsB=b.assetsByTeam[b.teamBId]||[]}
function saveDraft(){
 const b=ensureUnifiedBuilder();if(!unifiedReady())return showToast('Trade is incomplete','All participating teams must send and receive at least one item.');
 if(b.teamIds.length===2){syncLegacyTwoTeamBuilder();return saveDraftLegacyTwoTeam()}
 const a=me(),idValue=`MTD${String(Date.now()).slice(-6)}`,row={id:idValue,status:'draft',creatorId:a.id,teamIds:[...b.teamIds],transfers:structuredClone(unifiedTransfers()),note:b.note||'',acceptedBy:{},createdAt:now(),updatedAt:now()};multiTrades().unshift(row);save();clearBuilderRecovery();ui.builder=null;showToast('Private draft saved','Only the creator can see this multi-team draft.');setRoute('trade-center')
}
function submit(){
 const b=ensureUnifiedBuilder();if(!unifiedReady())return showToast('All teams must send and receive','Every participating franchise must send at least one item and receive at least one item before submission.');
 if(!builderTradeLimitsValid()){const bad=builderTradeLimitRows().find(r=>!r.allowed);return showToast('Team is out of trades',`${bad?.team?.fullName||'A participating team'} is out of trades. Please remove that team or reduce its outgoing assets to submit.`)}
 const transfers=unifiedTransfers(),check=window.FranchiseHQ?.tradeAssets?.validateTransfers?.(transfers);if(check&&!check.valid)return showToast('Trade assets need attention',check.errors?.[0]?.message||'Review asset ownership and duplicate items.');
 if(b.teamIds.length===2){syncLegacyTwoTeamBuilder();return submitLegacyTwoTeam()}
 ui.multiBuilder={teamIds:[...b.teamIds],transfers:structuredClone(transfers),note:b.note||'',multiTradeId:b.multiTradeId||b.tradeId||null};submitMultiTrade();clearBuilderRecovery();ui.builder=null
}
function startTeamTrade(teamId){const a=me();if(!a.teamId){showToast('Select a franchise identity','Switch to a team-owner or commissioner identity before building a trade.');return}clearBuilderRecovery();initBuilder();const b=ensureUnifiedBuilder();if(teamId&&teamId!==a.teamId&&!b.teamIds.includes(teamId)){b.teamIds.push(teamId);b.assetsByTeam[teamId]=[]}ui.tab='sent';setRoute('trade-center/new')}

function renderTeamTradeUsageModal(teamId){const team=teamById(teamId),records=approvedTradeRecords(teamId),rules=tradeRules(),remaining=remainingTradeCredits(teamId),modal=document.querySelector('[data-team-trade-usage-modal]'),content=document.querySelector('[data-team-trade-usage-content]');if(!modal||!content)return;content.innerHTML=`<div class="ownership-modal-header">${renderTeamMark(team,'team-logo')}<div><span class="eyebrow">Approved seasonal trade usage</span><h2>${escapeHtml(team.fullName)}</h2><p>${rules.limitEnabled?`${remaining} of ${rules.seasonTradeLimit} trades remaining`:'Unlimited trading enabled'}</p></div></div><section class="ownership-section"><h3>Approved trades</h3>${records.length?`<div class="team-trade-history">${records.map(r=>`<button type="button" class="team-trade-history-row" data-inline-approved-trade="${escapeHtml(String(r.id))}"><span><strong>Trade ${escapeHtml(r.id)}</strong><small>${r.teams.map(id=>teamById(id)?.abbr).filter(Boolean).join(' ↔ ')} · ${escapeHtml(r.at)}</small></span><b>${r.units} trade${r.units===1?'':'s'}</b></button>`).join('')}</div><div data-inline-approved-detail></div>`:'<p>No approved trades have used a seasonal trade.</p>'}</section>`;modal.classList.add('is-open');modal.setAttribute('aria-hidden','false')}

function suggestionAssetLine(asset){const val=value(asset);if(asset?.type==='player'){const p=playerById(asset.id);return `<button type="button" class="ai-asset-line" data-open-value-card="${escapeHtml(p?.id||asset.id)}"><span><b>${escapeHtml(p?.name||assetLabel(asset))}</b><small>${escapeHtml(p?`${p.position} · ${p.overall} OVR · ${p.dev}`:'Player')}</small></span><strong>${Number(val||0).toLocaleString()}</strong></button>`}return `<button type="button" class="ai-asset-line" data-open-pick-card="${asset.teamId}:${asset.year}:${asset.round}"><span><b>${escapeHtml(assetLabel(asset))}</b><small>Draft pick valuation</small></span><strong>${Number(val||0).toLocaleString()}</strong></button>`}
function suggestionPick(teamId,targetValue,currentValue){
 const years=[leagueYear()+1,leagueYear()+2,leagueYear()+3];
 const candidates=years.flatMap(year=>[1,2,3,4,5,6,7].map(round=>D(teamId,year,round)));
 return candidates.filter(asset=>value(asset)+currentValue<=targetValue*1.35).sort((a,b)=>Math.abs((currentValue+value(a))-targetValue)-Math.abs((currentValue+value(b))-targetValue))[0]||candidates.sort((a,b)=>Math.abs((currentValue+value(a))-targetValue)-Math.abs((currentValue+value(b))-targetValue))[0]||null;
}
function committeeFilterMarkup(){
 const options=[['needs-action','Needs My Review'],['participating','Trades I Am In'],['addressed','Already Reviewed']];
 return `<div class="committee-view-filters segmented-tabs">${options.map(([key,label])=>`<button class="${ui.committeeFilter===key?'is-active':''}" data-committee-filter="${key}">${label}</button>`).join('')}</div>`;
}
function saveCurrentBuilderDraft(){
 const b=ensureUnifiedBuilder();if(!builderHasWork(b))return showToast('Nothing to save','Add a team, asset, destination, or message before saving a draft.');
 store.savedDrafts=store.savedDrafts||[];const existingId=b.savedDraftId||null;const draft={id:existingId||id('draft'),creatorId:me().id,teamIds:[...b.teamIds],assetsByTeam:structuredClone(b.assetsByTeam||{}),destinations:{...(b.destinations||{})},note:b.note||'',tradeId:b.tradeId||null,multiTradeId:b.multiTradeId||null,updatedAt:now(),createdAt:b.createdAt||now()};
 const index=store.savedDrafts.findIndex(x=>x.id===draft.id);if(index>=0)store.savedDrafts[index]=draft;else store.savedDrafts.unshift(draft);save();clearBuilderRecovery();ui.builder=null;showToast('Draft saved','Open the Drafts tab to continue this trade later.');ui.tab='drafts';setRoute('trade-center/drafts');
}
function draftCards(){
 const rows=(store.savedDrafts||[]).filter(d=>d.creatorId===me().id);
 return rows.map(d=>{const names=(d.teamIds||[]).map(id=>teamById(id)?.abbr||id).join(' · '),count=Object.values(d.assetsByTeam||{}).reduce((n,list)=>n+(list?.length||0),0);return `<article class="trade-card card"><div><span class="eyebrow">Saved ${escapeHtml(d.updatedAt||'')}</span><h3>${escapeHtml(names||'Private Trade Draft')}</h3><p>${count} selected asset${count===1?'':'s'}</p></div><div class="heading-actions"><button class="button button--primary" data-open-saved-draft="${escapeHtml(d.id)}">Open Draft</button><button class="button button--danger button--subtle" data-delete-saved-draft="${escapeHtml(d.id)}">Delete</button></div></article>`}).join('');
}
function openSavedDraft(draftId){const d=(store.savedDrafts||[]).find(x=>x.id===draftId&&x.creatorId===me().id);if(!d)return showToast('Draft unavailable','This saved draft could not be found.');ui.builder={savedDraftId:d.id,teamIds:[...d.teamIds],assetsByTeam:structuredClone(d.assetsByTeam||{}),destinations:{...(d.destinations||{})},note:d.note||'',tradeId:d.tradeId||null,multiTradeId:d.multiTradeId||null,assetsA:[],assetsB:[]};ensureUnifiedBuilder();persistBuilderRecovery();setRoute('trade-center/new')}
function modifyMultiTrade(idValue){const t=multiTrades().find(x=>String(x.id).toLowerCase()===String(idValue).toLowerCase());if(t&&blockForApprovedAsset('multi',t))return;if(!t||!['negotiating','committee-rejected'].includes(t.status))return showToast('Modify Trade unavailable','This trade can no longer be modified.');if(!(t.teamIds||[]).includes(me().teamId)&&t.creatorId!==me().id)return showToast('Modify Trade unavailable','Only a participating owner may modify this trade.');ui.builder={multiTradeId:t.id,tradeId:null,teamIds:[...t.teamIds],assetsByTeam:Object.fromEntries((t.teamIds||[]).map(teamId=>[teamId,(t.transfers||[]).filter(x=>x.fromTeamId===teamId).map(x=>structuredClone(x.asset))])),destinations:Object.fromEntries((t.transfers||[]).map(x=>[unifiedAssetToken(x.fromTeamId,x.asset),x.toTeamId])),note:t.note||'',assetsA:[],assetsB:[]};ensureUnifiedBuilder();persistBuilderRecovery();setRoute('trade-center/new')}
function counterMultiTrade(idValue){const t=multiTrades().find(x=>String(x.id).toLowerCase()===String(idValue).toLowerCase());if(!t||t.status!=='negotiating'||!(t.teamIds||[]).includes(me().teamId))return showToast('Counter unavailable','This trade is not available for a counteroffer.');modifyMultiTrade(idValue)}
function declineMultiTrade(idValue){const t=multiTrades().find(x=>String(x.id).toLowerCase()===String(idValue).toLowerCase());if(!t||t.status!=='negotiating'||!(t.teamIds||[]).includes(me().teamId))return showToast('Reject unavailable','This trade is not available for rejection.');if(!confirm('Reject this entire multi-team trade?'))return;t.status='rejected';t.rejectedBy=me().id;t.rejectedByName=me().handle;t.rejectionSource='owner';t.updatedAt=now();t.chat=Array.isArray(t.chat)?t.chat:[];t.chat.push({id:id('multi-chat'),authorId:'system',text:`${me().handle} rejected the trade.`,at:now()});save();showToast('Trade rejected','The transaction has been closed for every participant.');renderMultiTradeDetail(t.id)}
function tradeAssetsCurrentForTwo(t){const v=ver(t);return [...(v?.assetsA||[]).map(asset=>({teamId:t.teamAId,asset})),...(v?.assetsB||[]).map(asset=>({teamId:t.teamBId,asset}))].every(row=>row.asset.type!=='player'||playerById(row.asset.id)?.teamId===row.teamId)}
function tradeAssetsCurrentForMulti(t){return (t.transfers||[]).every(row=>row.asset.type!=='player'||playerById(row.asset.id)?.teamId===row.fromTeamId)}
function approvedOutgoingAssetKeys(excludeId=''){const keys=new Set();negotiations().filter(t=>t.status==='approved'&&String(t.id)!==String(excludeId)).forEach(t=>{const v=ver(t);(v.assetsA||[]).forEach(a=>keys.add(`${t.teamAId}|${assetKey(a)}`));(v.assetsB||[]).forEach(a=>keys.add(`${t.teamBId}|${assetKey(a)}`))});multiTrades().filter(t=>t.status==='approved'&&String(t.id)!==String(excludeId)).forEach(t=>(t.transfers||[]).forEach(x=>keys.add(`${x.fromTeamId}|${assetKey(x.asset)}`)));return keys}
function approvedAssetConflictDetail(kind,t){const used=approvedOutgoingAssetKeys(t?.id);const rows=kind==='multi'?(t?.transfers||[]).map(x=>({teamId:x.fromTeamId,asset:x.asset})):(()=>{const v=ver(t);return [...(v?.assetsA||[]).map(asset=>({teamId:t.teamAId,asset})),...(v?.assetsB||[]).map(asset=>({teamId:t.teamBId,asset}))]})();const hit=rows.find(row=>used.has(`${row.teamId}|${assetKey(row.asset)}`));if(!hit)return null;return{...hit,label:assetLabel(hit.asset)}}
function blockForApprovedAsset(kind,t){const conflict=approvedAssetConflictDetail(kind,t);if(!conflict)return false;showToast('Trade asset no longer available',`${conflict.label} has been traded in an approved transaction and can no longer be involved in this trade. Please edit the trade to continue.`);return true}
function tradeHasApprovedAssetConflictTwo(t){const used=approvedOutgoingAssetKeys(t.id),v=ver(t);return [...(v?.assetsA||[]).map(a=>`${t.teamAId}|${assetKey(a)}`),...(v?.assetsB||[]).map(a=>`${t.teamBId}|${assetKey(a)}`)].some(k=>used.has(k))}
function tradeHasApprovedAssetConflictMulti(t){const used=approvedOutgoingAssetKeys(t.id);return (t.transfers||[]).some(x=>used.has(`${x.fromTeamId}|${assetKey(x.asset)}`))}
function cancelConflictingCommitteeTrades(){let changed=false;negotiations().filter(t=>t.status==='committee').forEach(t=>{if(tradeHasApprovedAssetConflictTwo(t)){t.status='rejected';t.rejectionSource='system';t.rejectedByName='Franchise HQ';t.cancelReason='Rejected: An asset in this trade was already approved in another transaction.';t.updatedAt=now();changed=true}});multiTrades().filter(t=>t.status==='committee').forEach(t=>{if(tradeHasApprovedAssetConflictMulti(t)){t.status='rejected';t.rejectionSource='system';t.rejectedByName='Franchise HQ';t.cancelReason='Rejected: An asset in this trade was already approved in another transaction.';t.updatedAt=now();changed=true}});if(changed)save()}
function autoCancelInvalidCommitteeTrades(){let changed=false;negotiations().filter(t=>t.status==='committee').forEach(t=>{if(!tradeAssetsCurrentForTwo(t)||tradeHasApprovedAssetConflictTwo(t)){t.status='rejected';t.rejectionSource='system';t.rejectedByName='Franchise HQ';t.cancelReason='Rejected: Player is no longer available from the sending team.';t.updatedAt=now();changed=true}});multiTrades().filter(t=>t.status==='committee').forEach(t=>{const limit=multiApprovalLimitCheck(t);if(!tradeAssetsCurrentForMulti(t)||tradeHasApprovedAssetConflictMulti(t)||limit?.ok===false){t.status='rejected';t.rejectionSource='system';t.rejectedByName='Franchise HQ';t.cancelReason=!tradeAssetsCurrentForMulti(t)?'Rejected: Player is no longer available from the sending team.':`Rejected: ${limit.message||'A participating team ran out of trades.'}`;t.updatedAt=now();changed=true}});if(changed)save()}
function cancelApprovedTrade(kind,idValue){if(me().role!=='commissioner')return showToast('Commissioner access required','Only a Commissioner may cancel an approved trade.');if(!confirm('Cancel this approved trade record? This does not alter Madden rosters.'))return;const row=kind==='multi'?multiTrades().find(x=>String(x.id)===String(idValue)):trade(idValue);if(!row||row.status!=='approved')return showToast('Cancellation unavailable','The approved trade could not be found.');row.status='cancelled';row.cancelledBy=me().id;row.cancelledAt=now();row.cancelReason='Cancelled by Commissioner';save();showToast('Approved trade cancelled','Trade usage has been recalculated.');renderRoute()}
